begin;
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('resumes', 'resumes', false, 10485760, array['application/pdf'])
on conflict (id) do update set public = false, file_size_limit = 10485760, allowed_mime_types = array['application/pdf'];
drop policy if exists "resume_objects_select_own" on storage.objects;
create policy "resume_objects_select_own" on storage.objects for select to authenticated using (bucket_id = 'resumes' and (storage.foldername(name))[1] = (select auth.uid())::text);
drop policy if exists "resume_objects_insert_own" on storage.objects;
create policy "resume_objects_insert_own" on storage.objects for insert to authenticated with check (bucket_id = 'resumes' and (storage.foldername(name))[1] = (select auth.uid())::text and lower(storage.extension(name)) = 'pdf');
drop policy if exists "resume_objects_update_own" on storage.objects;
create policy "resume_objects_update_own" on storage.objects for update to authenticated using (bucket_id = 'resumes' and (storage.foldername(name))[1] = (select auth.uid())::text) with check (bucket_id = 'resumes' and (storage.foldername(name))[1] = (select auth.uid())::text and lower(storage.extension(name)) = 'pdf');
drop policy if exists "resume_objects_delete_own" on storage.objects;
create policy "resume_objects_delete_own" on storage.objects for delete to authenticated using (bucket_id = 'resumes' and (storage.foldername(name))[1] = (select auth.uid())::text);
create or replace function public.handle_new_auth_user() returns trigger language plpgsql security definer set search_path = '' as $$ begin insert into public.profiles (user_id, email, full_name) values (new.id, new.email, nullif(trim(coalesce(new.raw_user_meta_data ->> 'full_name', '')), '')) on conflict (user_id) do update set email = excluded.email; return new; end; $$;
revoke all on function public.handle_new_auth_user() from public, anon, authenticated;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_auth_user();
insert into public.profiles (user_id, email, full_name) select u.id, u.email, nullif(trim(coalesce(u.raw_user_meta_data ->> 'full_name', '')), '') from auth.users as u on conflict (user_id) do nothing;
alter table public.resumes add constraint resumes_bucket_check check (storage_bucket = 'resumes');
alter table public.resumes add constraint resumes_owner_path_check check (storage_path like user_id::text || '/%');
alter table public.resumes add constraint resumes_pdf_metadata_check check (mime_type = 'application/pdf' and (file_size_bytes is null or file_size_bytes <= 10485760));
alter table public.resumes drop constraint if exists resumes_source_fk;
alter table public.resumes add constraint resumes_source_fk foreign key (user_id, source_resume_id) references public.resumes(user_id, id) on delete no action;
alter table public.applications drop constraint if exists applications_resume_fk;
alter table public.applications add constraint applications_resume_fk foreign key (user_id, resume_id) references public.resumes(user_id, id) on delete no action;
revoke insert, update, delete on public.profiles from authenticated;
revoke insert, update, delete on public.resumes from authenticated;
revoke insert, update, delete on public.applications from authenticated;
revoke insert, update, delete on public.execution_logs from authenticated;
revoke insert, update, delete on public.jobs from authenticated;
grant insert (user_id, external_id, source, source_url, company_name, company_website, title, description, location, country_code, employment_type, remote, salary_min, salary_max, salary_currency, required_skills, preferred_skills, experience_level, application_url, published_at, expires_at, pre_filter_score, pre_filter_passed, pre_filter_reasons, raw_metadata, is_active, scraped_at) on public.jobs to authenticated;
grant update (full_name, phone, location, linkedin_url, portfolio_url, headline, professional_summary, skills, preferred_locations, preferred_employment_types, min_salary, salary_currency, remote_preference) on public.profiles to authenticated;
grant insert (user_id, name, storage_bucket, storage_path, original_filename, mime_type, file_size_bytes, skills, is_default) on public.resumes to authenticated;
grant update (name, is_default) on public.resumes to authenticated;
grant insert (user_id, job_id, resume_id, notes) on public.applications to authenticated;
grant insert (user_id, application_id, job_id, execution_type, status, service_name, operation, attempt_number, duration_ms, error_code, error_message, fallback_reason, metadata) on public.execution_logs to authenticated;
commit;
